/* Local analysis workspace. Video and drafts never leave this browser. */
const studioKey='lockerdata.datasets.v1';
let studioData=[],studioWarning='',studioPoint=null,studioVideoURL=null,studioStorageBlocked=false;
try{studioData=JSON.parse(localStorage.getItem(studioKey)||'[]').map(LockerEngine.validateDataset);}catch{studioStorageBlocked=true;studioWarning='Không đọc được kho cục bộ. Hãy nhập bản JSON sao lưu; dữ liệu cũ chưa bị ghi đè. Phiên mới chỉ giữ trong bộ nhớ, cần xuất JSON.';}
const studio={id:studioData[0]?.id||'',player:'',type:'pass',direction:'right',from:0,to:130,h:4.5,compare:''};
function studioCurrent(){return studioData.find(d=>d.id===studio.id);}
function studioProvenance(d){return d?.provenance==='sample'?'Dữ liệu mô phỏng':'Nhập tay · Chưa kiểm chứng';}
function studioApplyFilter(){const from=Number($('#analysis-from').value),to=Number($('#analysis-to').value),h=Number($('#analysis-h').value);if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||to>130||to<from||h<2||h>10||!Number.isFinite(h))throw Error('Khoảng phút cần từ 0 đến 130, từ ≤ đến; bandwidth từ 2 đến 10m.');studio.from=from;studio.to=to;studio.h=h;studio.player=$('#analysis-player').value;studio.compare=$('#analysis-compare').value;render();}
function studioSave(){if(studioStorageBlocked){toast(studioWarning);return false;}try{localStorage.setItem(studioKey,JSON.stringify(studioData));studioWarning='';return true;}catch{studioWarning='Chưa lưu được vào trình duyệt. Hãy xuất JSON ngay để giữ dữ liệu.';toast(studioWarning);return false;}}
function studioDownload(text,name,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function studioCreate(){const id='local-'+Date.now(),d=LockerEngine.validateDataset({version:1,id,title:'Phiên phân tích mới',date:'',season:'2025/26',source:'Video do người dùng cung cấp',provenance:'manual_unverified',pitch:{length:105,width:68},players:archiveTeams.flatMap((t,side)=>[...t.starters.map(p=>({...studioRoster(p,side),starter:true})),...t.subs.map(p=>({...studioRoster(p,side),starter:false}))]),events:[]});studioData.push(d);studio.id=id;studio.player=d.players[0].id;studioSave();render();}
function studioRoster(p,side){return {id:`${side}-${p[0]}`,number:p[0],name:p[1],side,position:({TM:'GK',HV:'DF',TV:'MF','TĐ':'FW'})[p[2]]||'MF'};}
function studioOptions(d){return d.players.map(p=>`<option value="${esc(p.id)}" ${p.id===studio.player?'selected':''}>${p.side===0?'Nhà':'Khách'} · #${p.number} ${esc(p.name)}${p.starter?'':' · Dự bị'}</option>`).join('');}
function studioBar(){return `<div class="panel studio-toolbar"><label>Phiên phân tích<select id="studio-dataset">${studioData.map(d=>`<option value="${esc(d.id)}" ${d.id===studio.id?'selected':''}>${esc(d.title)} · ${d.events.length} sự kiện</option>`).join('')||'<option>Chưa có phiên</option>'}</select></label><button class="button primary" data-studio="new">+ Tạo phiên</button><label class="button">Nhập JSON<input id="studio-import" type="file" accept=".json,application/json" class="studio-file"></label><button class="button" data-studio="export" ${!studioCurrent()?'disabled':''}>Xuất JSON</button></div>${studioWarning?`<p role="alert" class="studio-warning">${esc(studioWarning)}</p>`:''}`;}
function studioPitch(content='',id=''){return `<svg ${id?`id="${id}"`:''} viewBox="0 0 105 68" role="img" aria-label="Sân bóng 105 × 68 mét" class="studio-pitch"><rect width="105" height="68" fill="#123c32"/>${content}<g fill="none" stroke="#d4e4d7" stroke-width=".3"><rect x=".5" y=".5" width="104" height="67"/><path d="M52.5 .5v67M.5 13.84h16v40.32H.5M104.5 13.84h-16v40.32h16M.5 24.84h5v18.32H.5M104.5 24.84h-5v18.32h5"/><circle cx="52.5" cy="34" r="9.15"/><circle cx="52.5" cy="34" r=".3"/></g></svg>`;}
function studioPage(){const d=studioCurrent();return heading('Video & nhập sự kiện','Xây dựng bộ dữ liệu theo trận · Video lưu trên máy', '<span class="sample-tag">'+studioProvenance(d)+'</span>')+studioBar()+(!d?'<section class="panel empty"><h2>Bắt đầu từ một video trận đấu</h2><p>Tạo phiên, xác nhận đội hình rồi đánh dấu các sự kiện. Bạn có thể xuất JSON để sao lưu và chuyển máy.</p><button class="button primary" data-studio="new">Tạo phiên đầu tiên</button></section>':`<p class="studio-note">Phiên mới mặc định dùng khung đội hình Hà Nội–CAHN 08/03/2026. Luôn xác nhận tên, số áo và vai trò cho đúng video hoặc JSON nhập vào. Đây chưa phải nguồn dữ liệu Opta. Lưu cục bộ trong trình duyệt; xuất JSON để sao lưu.</p><div class="studio-grid"><section class="panel studio-card"><label>Video trên máy<input type="file" id="studio-video" accept="video/*"></label><video id="studio-video-player" controls playsinline></video><div class="studio-controls"><label>Tốc độ<select id="studio-speed"><option value=".5">0.5×</option><option value=".75">0.75×</option><option value="1" selected>1×</option><option value="1.5">1.5×</option></select></label><button class="button" data-studio="timestamp">Lấy giờ video</button><label>Bù giờ video (phút)<input id="studio-offset" type="number" value="0" min="-130" max="130"></label></div><h3>Thông tin trận</h3><div class="studio-form"><label>Tên trận<input id="studio-title" maxlength="180" value="${esc(d.title)}"></label><label>Ngày<input id="studio-date" type="date" value="${esc(d.date)}"></label><label>Mùa<input id="studio-season" maxlength="30" value="${esc(d.season)}"></label><label>Nguồn / ghi chú<input id="studio-source" maxlength="500" value="${esc(d.source)}"></label></div><button class="button" data-studio="metadata">Lưu thông tin</button><details><summary>Xác nhận / chỉnh đội hình (${d.players.length} người)</summary><p>Tên chỉ dùng nhận diện trong phiên. Không ghép lịch sử cầu thủ giữa các trận dựa trên tên.</p><div class="table-wrap"><table><thead><tr><th>Tên</th><th>Áo</th><th>Vai trò</th><th>Đá chính</th></tr></thead><tbody>${d.players.map(p=>`<tr data-roster="${esc(p.id)}"><td><input aria-label="Tên cầu thủ ${esc(p.name)}" data-field="name" maxlength="120" value="${esc(p.name)}"></td><td><input aria-label="Số áo" data-field="number" type="number" min="1" max="999" value="${p.number}"></td><td><select aria-label="Vai trò" data-field="position">${['GK','DF','MF','FW'].map(v=>`<option ${v===p.position?'selected':''}>${v}</option>`).join('')}</select></td><td><input aria-label="Đá chính" data-field="starter" type="checkbox" ${p.starter?'checked':''}></td></tr>`).join('')}</tbody></table></div><button class="button" data-studio="roster">Lưu đội hình</button></details></section><section class="panel studio-card"><div class="studio-form"><label>Cầu thủ<select id="studio-player">${studioOptions(d)}</select></label><label>Sự kiện<select id="studio-type">${Object.entries(LockerEngine.definitions).map(([key,v])=>`<option value="${key}" ${key===studio.type?'selected':''}>${v.label}</option>`).join('')}</select></label><label>Phút<input id="studio-minute" type="number" min="0" max="130" value="0"></label><label>Giây<input id="studio-second" type="number" min="0" max="59" value="0"></label><label>Hiệp<select id="studio-period"><option value="1">Hiệp 1</option><option value="2">Hiệp 2</option><option value="3">Hiệp phụ 1</option><option value="4">Hiệp phụ 2</option></select></label><label>Hướng tấn công trên video<select id="studio-direction"><option value="right" ${studio.direction==='right'?'selected':''}>Sang phải →</option><option value="left" ${studio.direction==='left'?'selected':''}>← Sang trái</option></select></label></div><p id="studio-point-status" role="status">Bấm điểm bắt đầu trên sân. Chuyền bóng cần bấm thêm điểm nhận.</p>${studioPitch('','studio-tag-pitch')}<div class="studio-form"><label>Kết quả<select id="studio-success"><option value="true">Thành công</option><option value="false">Không thành công</option></select></label><label>Đối thủ (tùy chọn)<select id="studio-opponent"><option value="">Không ghi nhận</option>${d.players.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label>xG (nếu có nguồn)<input id="studio-xg" type="number" step=".01" min="0" max="1" placeholder="Để trống khi chưa có"></label><label>xGOT (cứu thua)<input id="studio-xgot" type="number" step=".01" min="0" max="1" placeholder="Để trống khi chưa có"></label></div><label><input id="studio-box" type="checkbox"> Đánh chặn nguy hiểm trong vùng cấm</label><div class="studio-controls"><button class="button primary" data-studio="event">Ghi sự kiện</button><button class="button" data-studio="point">Đặt lại điểm</button><button class="button" data-studio="undo" ${!d.events.length?'disabled':''}>Hoàn tác sự kiện cuối</button></div><p class="studio-note">Space: phát/dừng · P: chuyền · S: sút · T: tắc bóng · D: rê bóng · I: đánh chặn. Phím 1–9, 0, - chọn 11 cầu thủ đá chính của đội đang chọn. Phím tắt chỉ chạy ngoài ô nhập.</p><a class="button" href="#eventanalysis">Xem sơ đồ nhiệt & chấm điểm →</a></section></div><section class="panel studio-card"><h2>Nhật ký sự kiện · ${d.events.length}</h2><div class="table-wrap"><table><thead><tr><th>Giờ</th><th>Cầu thủ</th><th>Loại</th><th>Tọa độ chuẩn hóa (m)</th><th>Kết quả</th></tr></thead><tbody>${d.events.slice(-30).reverse().map(e=>`<tr><td>${e.minute}:${String(e.second).padStart(2,'0')}</td><td>${esc(d.players.find(p=>p.id===e.playerId).name)}</td><td>${LockerEngine.definitions[e.type].label}</td><td>${e.x.toFixed(1)}, ${e.y.toFixed(1)}${e.endX!==null?` → ${e.endX.toFixed(1)}, ${e.endY.toFixed(1)}`:''}</td><td>${e.success?'✓':'×'}</td></tr>`).join('')||'<tr><td colspan="5">Chưa có sự kiện.</td></tr>'}</tbody></table></div><p>Hiển thị 30 sự kiện gần nhất theo thời gian trận. Bản JSON chứa toàn bộ dữ liệu.</p></section>`);}
function studioHeat(d,p,rows,peak){const full=d.events.filter(e=>e.playerId===p.id&&!['yellow','red','penalty_foul'].includes(e.type)),points=rows.filter(e=>e.playerId===p.id&&!['yellow','red','penalty_foul'].includes(e.type)),grid=LockerEngine.kdeGrid(points,studio.h,40,26,Math.max(1,full.length)),scale=peak||Math.max(.00001,...LockerEngine.kdeGrid(full,studio.h));return studioPitch(grid.map((v,i)=>{const f=Math.min(1,v/scale);return f<.025?'':`<rect x="${i%40*2.625}" y="${Math.floor(i/40)*68/26}" width="2.7" height="2.7" fill="hsl(${240-240*f} 90% 55%)" opacity="${Math.min(.92,f*1.5)}"/>`;}).join('')+points.map(e=>`<circle cx="${e.x}" cy="${e.y}" r=".35" fill="white"><title>${e.minute}′ ${LockerEngine.definitions[e.type].label}</title></circle>`).join(''));}
function eventAnalysisPage(){const d=studioCurrent();if(!d)return heading('Phân tích sự kiện','Sơ đồ nhiệt & điểm số từ sự kiện bạn nhập')+studioBar()+'<section class="panel empty"><p>Chưa có bộ sự kiện. Hãy tạo phiên hoặc nhập JSON.</p><a class="button primary" href="#studio">Mở công cụ nhập video</a></section>';if(!d.players.some(p=>p.id===studio.player))studio.player=d.players[0].id;const p=d.players.find(p=>p.id===studio.player),rows=d.events.filter(e=>e.minute>=studio.from&&e.minute<=studio.to),r=LockerEngine.rating(rows,p),s=LockerEngine.stats(rows,p.id),other=d.players.find(p=>p.id===studio.compare),duel=other?LockerEngine.duel(rows,p.id,other.id):null;const ranked=d.players.map(p=>({p,r:LockerEngine.rating(rows,p)})).sort((a,b)=>(b.r.score??-1)-(a.r.score??-1));return heading('Phân tích sự kiện','Điểm minh bạch · Sơ đồ nhiệt theo cầu thủ và trận','<span class="sample-tag">'+studioProvenance(d)+'</span>')+studioBar()+`<div class="panel studio-card"><h2>${esc(d.title)}</h2><p>${esc(d.date||'Chưa xác định ngày')} · ${esc(d.season)} · ${esc(d.source)}</p><div class="studio-form"><label>Cầu thủ<select id="analysis-player">${studioOptions(d)}</select></label><label>Từ phút<input id="analysis-from" type="number" min="0" max="130" value="${studio.from}"></label><label>Đến phút<input id="analysis-to" type="number" min="0" max="130" value="${studio.to}"></label><label>KDE bandwidth (m)<input id="analysis-h" type="number" min="2" max="10" step=".5" value="${studio.h}"></label><label>Đối chiếu cầu thủ<select id="analysis-compare"><option value="">Không đối chiếu</option>${d.players.filter(x=>x.id!==p.id).map(x=>`<option value="${esc(x.id)}" ${x.id===studio.compare?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div><button class="button primary" data-studio="filter">Áp dụng bộ lọc</button></div><div class="studio-grid"><section class="panel studio-card"><h2>${esc(p.name)} · ${studio.from}–${studio.to}′</h2>${studioHeat(d,p,rows)}<p>Mật độ sự kiện có tọa độ, không phải thời gian hiện diện hay quãng đường chạy. Hướng chuẩn hóa →, sân 105 × 68m, Gaussian h=${studio.h}m. Thang màu cố định theo toàn phiên của cầu thủ.</p><button class="button" data-studio="svg">Tải sơ đồ SVG</button></section><section class="panel studio-card"><h2>Điểm ${r.score===null?'—':r.score.toFixed(2)} / 10</h2><p>LD-events-1.0 · nền 6.0 + đóng góp sự kiện, chặn 1–10. ${r.eventCount} sự kiện trong khoảng chọn. Chỉ là điểm tạm từ những gì đã nhập; chưa phản ánh toàn trận.</p><div class="studio-kpis"><div><b>${s.shots}</b>Dứt điểm</div><div><b>${s.passSuccess}/${s.passes}</b>Chuyền thành công</div><div><b>${s.xg===null?'—':s.xg.toFixed(2)}</b>xG · ${s.xgCoverage.join('/')} cú có nguồn</div></div><details open><summary>Đóng góp vào điểm</summary><ul>${r.breakdown.map(x=>`<li>${x.event.minute}′ · ${LockerEngine.definitions[x.event.type].label}: ${x.weight.toFixed(2)} × ${x.coefficient.toFixed(2)} = <b>${x.delta>0?'+':''}${x.delta.toFixed(3)}</b></li>`).join('')||'<li>Không có sự kiện cộng/trừ điểm.</li>'}</ul></details><p>Đánh chặn chỉ cộng khi đánh dấu nguy hiểm trong vùng cấm. Cứu thua GK: 0.25 + 0.25 × xGOT, thiếu xGOT dùng 0.25. Vai trò DF/MF thay cho nhóm hậu vệ biên/tiền vệ trụ; bonus đội = 0.</p></section></div>${other?`<section class="panel studio-card"><h2>Đối chiếu · ${esc(other.name)}</h2>${studioHeat(d,other,rows)}<p>Mỗi bản đồ dùng thang màu toàn phiên riêng, chỉ so sánh vị trí phân bố.</p><p>Tranh chấp đối đầu được gắn đối thủ: ${duel.total} · ${esc(p.name)} thắng ${duel.a} · ${esc(other.name)} thắng ${duel.b}. Không suy ra tranh chấp từ hai điểm chạm gần nhau.</p></section>`:''}<section class="panel studio-card"><h2>Nhịp sự kiện theo khoảng 5 phút</h2><div class="studio-momentum">${Array.from({length:27},(_,i)=>{const bin=rows.filter(e=>Math.floor(e.minute/5)===i),a=bin.filter(e=>d.players.find(p=>p.id===e.playerId).side===0).length,b=bin.length-a;return `<div title="${i*5}–${i*5+4}′ · Nhà ${a} / Khách ${b}"><span style="height:${Math.min(80,a*5)}px"></span><i style="height:${Math.min(80,b*5)}px"></i><small>${i*5}</small></div>`;}).join('')}</div><p>Xanh: đội nhà · Vàng: đội khách. Số sự kiện đã nhập; không phải kiểm soát bóng. Cột giới hạn hiển thị 16 sự kiện; xem số chính xác khi trỏ vào cột.</p></section><section class="panel studio-card"><h2>Điểm đội hình trong khoảng chọn</h2><p>Người đứng đầu bộ sự kiện: ${ranked[0].r.score!==null?esc(ranked[0].p.name)+' · '+ranked[0].r.score.toFixed(2):'Chưa có dữ liệu'}. Đây chưa phải MVP thực tế.</p><div class="table-wrap"><table><thead><tr><th>Cầu thủ</th><th>Đội</th><th>Vai trò</th><th>Trạng thái</th><th>Sự kiện</th><th>Điểm</th></tr></thead><tbody>${ranked.map(({p,r})=>`<tr><td>${esc(p.name)}</td><td>${p.side?'Khách':'Nhà'}</td><td>${p.position}</td><td>${p.starter?'Đá chính':'Dự bị'}</td><td>${r.eventCount}</td><td>${r.score===null?'—':r.score.toFixed(2)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function studioCapture(){const d=studioCurrent();if(!studioPoint?.start)throw Error('Chọn điểm bắt đầu trên sân.');if(LockerEngine.definitions[studio.type].end&&!studioPoint.end)throw Error('Bấm thêm điểm nhận cho đường chuyền.');const attrs={};for(const key of ['xg','xgot']){const v=$('#studio-'+key).value;if(v!=='')attrs[key]=Number(v);}if($('#studio-box').checked)attrs.inBox=true;if($('#studio-opponent').value)attrs.opponentId=$('#studio-opponent').value;const e={id:'event-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),matchId:d.id,playerId:$('#studio-player').value,type:studio.type,minute:Number($('#studio-minute').value),second:Number($('#studio-second').value),period:Number($('#studio-period').value),...studioPoint.start,endX:studioPoint.end?.x??null,endY:studioPoint.end?.y??null,success:$('#studio-success').value==='true',attributes:attrs};const checked=LockerEngine.validateDataset({...d,events:[...d.events,e]});Object.assign(d,checked);studioPoint=null;studioSave();const v=$('#studio-video-player'),saved={url:v.currentSrc,time:v.currentTime,rate:v.playbackRate,minute:$('#studio-minute').value,second:$('#studio-second').value,period:$('#studio-period').value,offset:$('#studio-offset').value};render();if(saved.url){const player=$('#studio-video-player');player.src=saved.url;player.addEventListener('loadedmetadata',()=>{player.currentTime=saved.time;player.playbackRate=saved.rate;},{once:true});}$('#studio-speed').value=String(saved.rate);for(const k of ['minute','second','period','offset'])$('#studio-'+k).value=saved[k];toast('Đã ghi sự kiện.');}
document.addEventListener('click',e=>{const pitch=e.target.closest('#studio-tag-pitch');if(pitch){const box=pitch.getBoundingClientRect(),x=(e.clientX-box.left)/box.width*105,y=(e.clientY-box.top)/box.height*68,point=LockerEngine.normalize(Math.max(0,Math.min(105,x)),Math.max(0,Math.min(68,y)),studio.direction);if(!studioPoint?.start||studioPoint.end)studioPoint={start:point};else studioPoint.end=point;$('#studio-point-status').textContent=`Đầu: ${studioPoint.start.x.toFixed(1)}, ${studioPoint.start.y.toFixed(1)}m${studioPoint.end?' → '+studioPoint.end.x.toFixed(1)+', '+studioPoint.end.y.toFixed(1)+'m':''}`;pitch.innerHTML=studioPitch(`<circle cx="${x}" cy="${y}" r="1" fill="#ffdb5d"/>`).match(/<svg[^>]*>([\s\S]*)<\/svg>/)[1];}const action=e.target.closest('[data-studio]')?.dataset.studio;if(!action)return;try{const d=studioCurrent();if(action==='filter')studioApplyFilter();if(action==='new')studioCreate();if(action==='export'&&d)studioDownload(JSON.stringify(d,null,2),'LockerData-'+d.id+'.json');if(action==='metadata'){const checked=LockerEngine.validateDataset({...d,title:$('#studio-title').value,date:$('#studio-date').value,season:$('#studio-season').value,source:$('#studio-source').value});Object.assign(d,checked);studioSave();toast('Đã lưu thông tin.');}if(action==='roster'){const copy=d.players.map(p=>{const row=document.querySelector(`[data-roster="${CSS.escape(p.id)}"]`);return {...p,name:row.querySelector('[data-field="name"]').value,number:Number(row.querySelector('[data-field="number"]').value),position:row.querySelector('[data-field="position"]').value,starter:row.querySelector('[data-field="starter"]').checked};});Object.assign(d,LockerEngine.validateDataset({...d,players:copy}));studioSave();render();}if(action==='event')studioCapture();if(action==='point'){studioPoint=null;$('#studio-point-status').textContent='Bấm điểm bắt đầu trên sân.';}if(action==='undo'){const latest=d.events.reduce((best,event)=>!best||event.id>best.id?event:best,null);if(latest)d.events=d.events.filter(e=>e.id!==latest.id);studioSave();render();}if(action==='timestamp'){const t=$('#studio-video-player').currentTime+Number($('#studio-offset').value)*60;$('#studio-minute').value=Math.floor(t/60);$('#studio-second').value=Math.floor(t%60);}if(action==='svg'){const p=d.players.find(p=>p.id===studio.player),rows=d.events.filter(e=>e.minute>=studio.from&&e.minute<=studio.to);const svg=studioHeat(d,p,rows).replace('<svg ',`<svg xmlns="http://www.w3.org/2000/svg" `).replace('viewBox="0 0 105 68"','viewBox="0 0 105 78"').replace('</svg>',`<text x="2" y="72" font-size="2" fill="black">${esc(d.title)} · ${esc(p.name)} · ${studio.from}–${studio.to}′</text><text x="2" y="76" font-size="2" fill="black">LockerData.VN · ${esc(studioProvenance(d))} · h=${studio.h}m</text></svg>`);studioDownload(svg,'LockerData-heat.svg','image/svg+xml');}}catch(err){toast(err.message);}});
document.addEventListener('change',async e=>{const id=e.target.id;try{if(id==='studio-dataset'){studio.id=e.target.value;studio.player='';studioPoint=null;render();}if(id==='studio-player')studio.player=e.target.value;if(id==='studio-type'){studio.type=e.target.value;studioPoint=null;}if(id==='studio-direction'){studio.direction=e.target.value;studioPoint=null;}if(id==='studio-video'){const file=e.target.files[0];if(file){if(studioVideoURL)URL.revokeObjectURL(studioVideoURL);studioVideoURL=URL.createObjectURL(file);$('#studio-video-player').src=studioVideoURL;}}if(id==='studio-speed')$('#studio-video-player').playbackRate=Number(e.target.value);if(id==='studio-import'){const f=e.target.files[0];if(!f)return;if(f.size>8000000)throw Error('File vượt giới hạn 8MB.');const imported=LockerEngine.validateDataset(JSON.parse(await f.text()));if(studioData.some(d=>d.id===imported.id))throw Error('Mã phiên đã có. Dữ liệu hiện tại được giữ nguyên; dùng mã phiên khác để nhập bản sao.');studioData.push(imported);studio.id=imported.id;studio.player='';studioSave();render();toast('Đã nhập JSON hợp lệ.');}if(id.startsWith('analysis-')){if(id==='analysis-player')studio.player=e.target.value;if(id==='analysis-compare')studio.compare=e.target.value;if(id==='analysis-from')studio.from=Math.max(0,Math.min(studio.to,Math.trunc(Number(e.target.value))||0));if(id==='analysis-to')studio.to=Math.max(studio.from,Math.min(130,Math.trunc(Number(e.target.value))||0));if(id==='analysis-h')studio.h=Math.max(2,Math.min(10,Number(e.target.value)||4.5));render();}}catch(err){toast(err.message);}});
document.addEventListener('keydown',e=>{if(state.page!=='studio'||/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;const v=$('#studio-video-player');if(e.code==='Space'&&v){e.preventDefault();v.paused?v.play().catch(()=>toast('Chọn video trước.')):v.pause();}const types={p:'pass',s:'shot',t:'tackle',d:'dribble',i:'interception'};if(types[e.key.toLowerCase()]){studio.type=types[e.key.toLowerCase()];$('#studio-type').value=studio.type;studioPoint=null;}const index='1234567890-'.indexOf(e.key);if(index>=0&&e.key.length===1){const d=studioCurrent(),side=d?.players.find(p=>p.id===$('#studio-player').value)?.side||0,p=d?.players.filter(p=>p.side===side&&p.starter)[index];if(p){studio.player=p.id;$('#studio-player').value=p.id;}}});
pageViews.studio=studioPage;pageViews.eventanalysis=eventAnalysisPage;nav.splice(nav.length-1,0,['studio','Video & nhập liệu','pitch'],['eventanalysis','Phân tích sự kiện','chart']);
const previousStudioHeat=pageViews.heatmap;pageViews.heatmap=()=>`<div class="heat-lab-link"><a class="button" href="#eventanalysis">Phân tích sơ đồ nhiệt từ video / JSON của bạn →</a></div>`+previousStudioHeat();
let studioPlayback={time:0,rate:1};
const priorStudioRender=render;
render=function(){
  const old=document.querySelector('#studio-video-player');
  if(old?.currentSrc)studioPlayback={time:old.currentTime,rate:old.playbackRate};
  priorStudioRender();
  const video=document.querySelector('#studio-video-player');
  if(state.page==='studio'&&video&&studioVideoURL){
    video.src=studioVideoURL;
    video.addEventListener('loadedmetadata',()=>{video.currentTime=studioPlayback.time;video.playbackRate=studioPlayback.rate;},{once:true});
    document.querySelector('#studio-speed').value=String(studioPlayback.rate);
  }
};
const priorStudioOverview=overview;
overview=function(){return priorStudioOverview()+`<div class="explore-links"><a class="panel" href="#studio"><b>Nhập sự kiện từ video →</b><span>Tạo kho dữ liệu theo trận và sao lưu JSON</span></a><a class="panel" href="#eventanalysis"><b>Chấm điểm có bảng đóng góp →</b><span>KDE theo mét, lọc phút và đối chiếu cầu thủ</span></a></div>`;};
pageViews.overview=overview;
const priorStudioSources=pageViews.sources;
pageViews.sources=()=>priorStudioSources()+`<section class="panel studio-card"><h2>Phương pháp bổ sung v5</h2><p>Video & nhập liệu tạo dữ liệu cục bộ chưa kiểm chứng. Gaussian KDE dùng sân 105×68m, h=4.5m. LD-events-1.0 dùng nền 6 và bảng đóng góp có hệ số vai trò; người chưa có sự kiện chưa nhận điểm. Không phải điểm Sofascore hay Opta.</p><p>Định giá đang dùng LD-value-2.0: giá nền × (điểm×0.35 + đóng góp×0.25) × tuổi × tuyển × hợp đồng × giải. Tỷ giá 26.500 là giả định chỉnh được; VNĐ là tổng lót tay mô phỏng. Phần công thức định giá trước đó mô tả mô hình mẫu cũ.</p><p>Chưa kết nối CSDL máy chủ, đăng nhập, live API hay nguồn Opta cấp phép. JSON sao lưu không chứa video; dữ liệu chỉ được nhập và lưu tại trình duyệt.</p></section>`;
render();
